//! Embedded, pre-decoded artwork, glyphs and design tokens (generated by
//! `build.rs`).
//!
//! Nothing here is parsed at run time: the mark is premultiplied RGBA, the
//! glyphs are coverage bytes, and the colours, the type styles and the
//! corner radius come from the Boswas UI token file
//! (`desktop/ui/tokens.json`).

use crate::gfx::Rgb;

/// One glyph of an atlas, in pixels at [`Face::px`].
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    /// Start of the `width * height` coverage bytes in [`Face::coverage`].
    pub offset: usize,
    pub width: usize,
    pub height: usize,
    /// Horizontal offset of the bitmap from the pen position.
    pub left: i32,
    /// Offset of the bitmap's bottom edge above the baseline.
    pub bottom: i32,
    /// Pen advance.
    pub advance: f32,
}

/// One weight of the typeface: the glyphs `first..=last` at one large size.
#[derive(Debug)]
pub struct Face {
    /// Pixel size the atlas was rasterised at.
    pub px: f32,
    /// Distance from the top of a line to the baseline, at [`Face::px`].
    pub ascent: f32,
    /// Distance from the baseline to the bottom of a line (negative).
    pub descent: f32,
    pub first: u8,
    pub last: u8,
    pub coverage: &'static [u8],
    pub glyphs: &'static [Glyph],
}

/// The weights the boot screen sets text in.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Weight {
    Regular,
    SemiBold,
}

impl Weight {
    pub fn face(self) -> &'static Face {
        match self {
            Weight::Regular => &REGULAR,
            Weight::SemiBold => &SEMIBOLD,
        }
    }
}

/// An entry of the type ramp, in logical pixels.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TextStyle {
    pub size: f32,
    /// Height of a line of text in this style.
    pub line: f32,
    pub weight: Weight,
}

include!(concat!(env!("OUT_DIR"), "/assets.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_assets_are_consistent() {
        assert_eq!(MARK_RGBA.len(), (MARK_WIDTH * MARK_HEIGHT * 4) as usize);
        for face in [&REGULAR, &SEMIBOLD] {
            assert_eq!(face.glyphs.len(), (face.last - face.first + 1) as usize);
            assert!(face.ascent > 0.0 && face.descent < 0.0 && face.px >= 32.0);
            for g in face.glyphs.iter() {
                assert!(g.offset + g.width * g.height <= face.coverage.len());
                assert!(g.advance > 0.0);
            }
            assert!(face.coverage.contains(&255));
        }
        // The mark is premultiplied: no colour channel exceeds alpha.
        for px in MARK_RGBA.chunks_exact(4) {
            assert!(px[0] <= px[3] && px[1] <= px[3] && px[2] <= px[3]);
        }
        // It has both transparent and opaque pixels.
        assert!(MARK_RGBA.chunks_exact(4).any(|p| p[3] == 0));
        assert!(MARK_RGBA.chunks_exact(4).any(|p| p[3] == 255));
        assert!(TYPEFACE == "Inter" || TYPEFACE == "Orbitron");
    }

    #[test]
    fn the_semibold_face_is_heavier() {
        // The same letters cover more in the heavier weight, size for size.
        let ink = |face: &Face| {
            let covered: f64 = "Unlock"
                .bytes()
                .map(|ch| {
                    let g = &face.glyphs[(ch - face.first) as usize];
                    face.coverage[g.offset..g.offset + g.width * g.height].iter().map(|&v| v as f64).sum::<f64>()
                })
                .sum();
            covered / (face.px as f64 * face.px as f64)
        };
        assert!(ink(&SEMIBOLD) > ink(&REGULAR) * 1.08, "{} vs {}", ink(&SEMIBOLD), ink(&REGULAR));
    }

    #[test]
    fn tokens_come_from_the_token_file() {
        // desktop/ui/tokens.json: neutral.950, iris.400 and the dark theme.
        assert_eq!(BACKGROUND, Rgb::new(0x18, 0x17, 0x1C));
        assert_eq!(ACCENT, Rgb::new(0x9B, 0x8A, 0xFF));
        assert_eq!(TEXT, Rgb::new(255, 255, 255));
        assert_eq!(DANGER, Rgb::new(0xFF, 0x77, 0x88));
        assert_eq!(WARNING, Rgb::new(0xFF, 0xC2, 0x4F));
        // The control fill is a little lighter than the background, and its
        // outline a little lighter again.
        let light = |colour: Rgb| colour.r as u32 + colour.g as u32 + colour.b as u32;
        assert!(light(FIELD_FILL) > light(BACKGROUND) && light(FIELD_STROKE) > light(FIELD_FILL));
        assert!(light(FIELD_STROKE) < light(BACKGROUND) + 3 * 48, "subtle: {FIELD_FILL:?}, {FIELD_STROKE:?}");
        assert_eq!(RADIUS_CONTROL, 4.0);
        assert_eq!(CAPTION, TextStyle { size: 12.0, line: 16.0, weight: Weight::Regular });
        assert_eq!(BODY, TextStyle { size: 14.0, line: 20.0, weight: Weight::Regular });
        assert_eq!(BODY_LARGE, TextStyle { size: 16.0, line: 22.0, weight: Weight::Regular });
        assert_eq!(SUBTITLE, TextStyle { size: 20.0, line: 28.0, weight: Weight::SemiBold });
    }
}
